use stack_machine::eval;

#[test]
fn test_simple_add() {
    assert_eq!(eval("3 4 +"), Ok(7));
}

#[test]
fn test_chain() {
    assert_eq!(eval("5 1 2 + 4 * + 3 -"), Ok(14));
}

#[test]
fn test_subtract() {
    assert_eq!(eval("10 3 -"), Ok(7));
}

#[test]
fn test_multiply_divide() {
    assert_eq!(eval("6 7 *"), Ok(42));
    assert_eq!(eval("10 2 /"), Ok(5));
}

#[test]
fn test_divide_by_zero() {
    assert!(eval("5 0 /").is_err());
}

#[test]
fn test_invalid_token() {
    assert!(eval("1 x +").is_err());
}
